WITH candidate AS (SELECT b.mktcode,b.tgtcode,AVG(b.volume) AS metric FROM `newzl`.`hsj_stock_hq_basic` AS b WHERE b.mktcode=1 AND b.bizdate IN ('2026-04-14','2026-04-13','2026-04-10','2026-04-09','2026-04-08') GROUP BY b.mktcode,b.tgtcode), benchmark AS (SELECT AVG(b.volume) AS metric FROM `newzl`.`hsj_stock_hq_basic` AS b INNER JOIN `newzl`.`hsj_stock_code_info` AS s ON s.mktcode=b.mktcode AND s.tgtcode=b.tgtcode WHERE s.name='贵州茅台' AND b.bizdate IN ('2026-04-14','2026-04-13','2026-04-10','2026-04-09','2026-04-08')) SELECT a.mktcode,a.tgtcode,a.bizdate FROM `newzl`.`hsj_stock_hq_basic` AS a INNER JOIN candidate AS c ON c.mktcode=a.mktcode AND c.tgtcode=a.tgtcode CROSS JOIN benchmark AS q WHERE a.bizdate='2026-04-14' AND c.metric>q.metric;
